203	  private DefaultRequestInterceptorREST createInterceptorForSubCluster(
204	      SubClusterId subClusterId, String webAppAddress) {
205	
206	    final Configuration conf = this.getConf();
207	
208	    String interceptorClassName = conf.get(
209	        YarnConfiguration.ROUTER_WEBAPP_DEFAULT_INTERCEPTOR_CLASS,
210	        YarnConfiguration.DEFAULT_ROUTER_WEBAPP_DEFAULT_INTERCEPTOR_CLASS);
