212	    try {
213	      Class<?> interceptorClass = conf.getClassByName(interceptorClassName);
214	      if (DefaultRequestInterceptorREST.class
215	          .isAssignableFrom(interceptorClass)) {
216	        interceptorInstance = (DefaultRequestInterceptorREST) ReflectionUtils
217	            .newInstance(interceptorClass, conf);
218	
219	      } else {
220	        throw new YarnRuntimeException(
221	            "Class: " + interceptorClassName + " not instance of "
222	                + DefaultRequestInterceptorREST.class.getCanonicalName());
