251	  /**
252	   * YARN Router forwards every getNewApplication requests to any RM. During
253	   * this operation there will be no communication with the State Store. The
254	   * Router will forward the requests to any SubCluster. The Router will retry
255	   * to submit the request on #numSubmitRetries different SubClusters. The
256	   * SubClusters are randomly chosen from the active ones.
257	   * <p>
258	   * Possible failures and behaviors:
259	   * <p>
260	   * Client: identical behavior as {@code RMWebServices}.
261	   * <p>
262	   * Router: the Client will timeout and resubmit.
263	   * <p>
264	   * ResourceManager: the Router will timeout and contacts another RM.
265	   * <p>
266	   * StateStore: not in the execution.
267	   */
268	  @Override
269	  public Response createNewApplication(HttpServletRequest hsr)
270	      throws AuthorizationException, IOException, InterruptedException {
271	
272	    long startTime = clock.getTime();
273	
274	    Map<SubClusterId, SubClusterInfo> subClustersActive;
275	    try {
276	      subClustersActive = federationFacade.getSubClusters(true);
277	    } catch (YarnException e) {
278	      routerMetrics.incrAppsFailedCreated();
279	      return Response.status(Status.INTERNAL_SERVER_ERROR)
280	          .entity(e.getLocalizedMessage()).build();
281	    }
282	
283	    List<SubClusterId> blacklist = new ArrayList<SubClusterId>();
284	
285	    for (int i = 0; i < numSubmitRetries; ++i) {
286	
287	      SubClusterId subClusterId;
288	      try {
289	        subClusterId = getRandomActiveSubCluster(subClustersActive, blacklist);
290	      } catch (YarnException e) {
291	        routerMetrics.incrAppsFailedCreated();
292	        return Response.status(Status.SERVICE_UNAVAILABLE)
293	            .entity(e.getLocalizedMessage()).build();
294	      }
295	
296	      LOG.debug("getNewApplication try #{} on SubCluster {}", i, subClusterId);
297	
298	      DefaultRequestInterceptorREST interceptor =
299	          getOrCreateInterceptorForSubCluster(subClusterId,
300	              subClustersActive.get(subClusterId).getRMWebServiceAddress());
301	      Response response = null;
302	      try {
303	        response = interceptor.createNewApplication(hsr);
304	      } catch (Exception e) {
305	        LOG.warn("Unable to create a new ApplicationId in SubCluster {}",
306	            subClusterId.getId(), e);
307	      }
308	
309	      if (response != null &&
310	          response.getStatus() == HttpServletResponse.SC_OK) {
311	
312	        long stopTime = clock.getTime();
313	        routerMetrics.succeededAppsCreated(stopTime - startTime);
314	
315	        return response;
316	      } else {
317	        // Empty response from the ResourceManager.
318	        // Blacklist this subcluster for this request.
319	        blacklist.add(subClusterId);
320	      }
321	    }
322	
323	    String errMsg = "Fail to create a new application.";
324	    LOG.error(errMsg);
325	    routerMetrics.incrAppsFailedCreated();
326	    return Response
327	        .status(Status.INTERNAL_SERVER_ERROR)
328	        .entity(errMsg)
329	        .build();
330	  }
