332	  /**
333	   * Today, in YARN there are no checks of any applicationId submitted.
334	   * <p>
335	   * Base scenarios:
336	   * <p>
337	   * The Client submits an application to the Router. The Router selects one
338	   * SubCluster to forward the request. The Router inserts a tuple into
339	   * StateStore with the selected SubCluster (e.g. SC1) and the appId. The
340	   * State Store replies with the selected SubCluster (e.g. SC1). The Router
341	   * submits the request to the selected SubCluster.
342	   * <p>
343	   * In case of State Store failure:
344	   * <p>
345	   * The client submits an application to the Router. The Router selects one
346	   * SubCluster to forward the request. The Router inserts a tuple into State
347	   * Store with the selected SubCluster (e.g. SC1) and the appId. Due to the
348	   * State Store down the Router times out and it will retry depending on the
349	   * FederationFacade settings. The Router replies to the client with an error
350	   * message.
351	   * <p>
352	   * If State Store fails after inserting the tuple: identical behavior as
353	   * {@code RMWebServices}.
354	   * <p>
355	   * In case of Router failure:
356	   * <p>
357	   * Scenario 1 – Crash before submission to the ResourceManager
358	   * <p>
359	   * The Client submits an application to the Router. The Router selects one
360	   * SubCluster to forward the request. The Router inserts a tuple into State
361	   * Store with the selected SubCluster (e.g. SC1) and the appId. The Router
362	   * crashes. The Client timeouts and resubmits the application. The Router
363	   * selects one SubCluster to forward the request. The Router inserts a tuple
364	   * into State Store with the selected SubCluster (e.g. SC2) and the appId.
365	   * Because the tuple is already inserted in the State Store, it returns the
366	   * previous selected SubCluster (e.g. SC1). The Router submits the request
367	   * to the selected SubCluster (e.g. SC1).
368	   * <p>
369	   * Scenario 2 – Crash after submission to the ResourceManager
370	   * <p>
371	   * The Client submits an application to the Router. The Router selects one
372	   * SubCluster to forward the request. The Router inserts a tuple into State
373	   * Store with the selected SubCluster (e.g. SC1) and the appId. The Router
374	   * submits the request to the selected SubCluster. The Router crashes. The
375	   * Client timeouts and resubmit the application. The Router selects one
376	   * SubCluster to forward the request. The Router inserts a tuple into State
377	   * Store with the selected SubCluster (e.g. SC2) and the appId. The State
378	   * Store replies with the selected SubCluster (e.g. SC1). The Router submits
379	   * the request to the selected SubCluster (e.g. SC1). When a client re-submits
380	   * the same application to the same RM, it does not raise an exception and
381	   * replies with operation successful message.
382	   * <p>
383	   * In case of Client failure: identical behavior as {@code RMWebServices}.
384	   * <p>
385	   * In case of ResourceManager failure:
386	   * <p>
387	   * The Client submits an application to the Router. The Router selects one
388	   * SubCluster to forward the request. The Router inserts a tuple into State
389	   * Store with the selected SubCluster (e.g. SC1) and the appId. The Router
390	   * submits the request to the selected SubCluster. The entire SubCluster is
391	   * down – all the RMs in HA or the master RM is not reachable. The Router
392	   * times out. The Router selects a new SubCluster to forward the request.
393	   * The Router update a tuple into State Store with the selected SubCluster
394	   * (e.g. SC2) and the appId. The State Store replies with OK answer. The
395	   * Router submits the request to the selected SubCluster (e.g. SC2).
396	   */
397	  @Override
398	  public Response submitApplication(ApplicationSubmissionContextInfo newApp,
399	      HttpServletRequest hsr)
400	      throws AuthorizationException, IOException, InterruptedException {
401	
402	    long startTime = clock.getTime();
403	
404	    if (newApp == null || newApp.getApplicationId() == null) {
405	      routerMetrics.incrAppsFailedSubmitted();
406	      String errMsg = "Missing ApplicationSubmissionContextInfo or "
407	          + "applicationSubmissionContex information.";
408	      return Response
409	          .status(Status.BAD_REQUEST)
410	          .entity(errMsg)
411	          .build();
412	    }
413	
414	    ApplicationId applicationId = null;
415	    try {
416	      applicationId = ApplicationId.fromString(newApp.getApplicationId());
417	    } catch (IllegalArgumentException e) {
418	      routerMetrics.incrAppsFailedSubmitted();
419	      return Response
420	          .status(Status.BAD_REQUEST)
421	          .entity(e.getLocalizedMessage())
422	          .build();
423	    }
424	
425	    List<SubClusterId> blacklist = new ArrayList<SubClusterId>();
426	
427	    for (int i = 0; i < numSubmitRetries; ++i) {
428	
429	      ApplicationSubmissionContext context =
430	          RMWebAppUtil.createAppSubmissionContext(newApp, this.getConf());
431	
432	      SubClusterId subClusterId = null;
433	      try {
434	        subClusterId = policyFacade.getHomeSubcluster(context, blacklist);
435	      } catch (YarnException e) {
436	        routerMetrics.incrAppsFailedSubmitted();
437	        return Response
438	            .status(Status.SERVICE_UNAVAILABLE)
439	            .entity(e.getLocalizedMessage())
440	            .build();
441	      }
442	      LOG.info("submitApplication appId {} try #{} on SubCluster {}",
443	          applicationId, i, subClusterId);
444	
445	      ApplicationHomeSubCluster appHomeSubCluster =
446	          ApplicationHomeSubCluster.newInstance(applicationId, subClusterId);
447	
448	      if (i == 0) {
449	        try {
450	          // persist the mapping of applicationId and the subClusterId which has
451	          // been selected as its home
452	          subClusterId =
453	              federationFacade.addApplicationHomeSubCluster(appHomeSubCluster);
454	        } catch (YarnException e) {
455	          routerMetrics.incrAppsFailedSubmitted();
456	          String errMsg = "Unable to insert the ApplicationId " + applicationId
457	              + " into the FederationStateStore";
458	          return Response
459	              .status(Status.SERVICE_UNAVAILABLE)
460	              .entity(errMsg + " " + e.getLocalizedMessage())
461	              .build();
462	        }
463	      } else {
464	        try {
465	          // update the mapping of applicationId and the home subClusterId to
466	          // the new subClusterId we have selected
467	          federationFacade.updateApplicationHomeSubCluster(appHomeSubCluster);
468	        } catch (YarnException e) {
469	          String errMsg = "Unable to update the ApplicationId " + applicationId
470	              + " into the FederationStateStore";
471	          SubClusterId subClusterIdInStateStore;
472	          try {
473	            subClusterIdInStateStore =
474	                federationFacade.getApplicationHomeSubCluster(applicationId);
475	          } catch (YarnException e1) {
476	            routerMetrics.incrAppsFailedSubmitted();
477	            return Response
478	                .status(Status.SERVICE_UNAVAILABLE)
479	                .entity(e1.getLocalizedMessage())
480	                .build();
481	          }
482	          if (subClusterId == subClusterIdInStateStore) {
483	            LOG.info("Application {} already submitted on SubCluster {}",
484	                applicationId, subClusterId);
485	          } else {
486	            routerMetrics.incrAppsFailedSubmitted();
487	            return Response
488	                .status(Status.SERVICE_UNAVAILABLE)
489	                .entity(errMsg)
490	                .build();
491	          }
492	        }
493	      }
494	
495	      SubClusterInfo subClusterInfo;
496	      try {
497	        subClusterInfo = federationFacade.getSubCluster(subClusterId);
498	      } catch (YarnException e) {
499	        routerMetrics.incrAppsFailedSubmitted();
500	        return Response
501	            .status(Status.SERVICE_UNAVAILABLE)
502	            .entity(e.getLocalizedMessage())
503	            .build();
504	      }
505	
506	      Response response = null;
507	      try {
508	        response = getOrCreateInterceptorForSubCluster(subClusterId,
509	            subClusterInfo.getRMWebServiceAddress()).submitApplication(newApp,
510	                hsr);
511	      } catch (Exception e) {
512	        LOG.warn("Unable to submit the application {} to SubCluster {}",
513	            applicationId, subClusterId.getId(), e);
514	      }
515	
516	      if (response != null &&
517	          response.getStatus() == HttpServletResponse.SC_ACCEPTED) {
518	        LOG.info("Application {} with appId {} submitted on {}",
519	            context.getApplicationName(), applicationId, subClusterId);
520	
521	        long stopTime = clock.getTime();
522	        routerMetrics.succeededAppsSubmitted(stopTime - startTime);
523	
524	        return response;
525	      } else {
526	        // Empty response from the ResourceManager.
527	        // Blacklist this subcluster for this request.
528	        blacklist.add(subClusterId);
529	      }
530	    }
531	
532	    routerMetrics.incrAppsFailedSubmitted();
533	    String errMsg = "Application " + newApp.getApplicationName()
534	        + " with appId " + applicationId + " failed to be submitted.";
535	    LOG.error(errMsg);
536	    return Response
537	        .status(Status.SERVICE_UNAVAILABLE)
538	        .entity(errMsg)
539	        .build();
540	  }
