749	  /**
750	   * Get a copy of a HTTP request. This is for thread safety.
751	   * @param hsr HTTP servlet request to copy.
752	   * @return Copy of the HTTP request.
753	   */
754	  private HttpServletRequestWrapper clone(final HttpServletRequest hsr) {
755	    if (hsr == null) {
756	      return null;
757	    }
758	    @SuppressWarnings("unchecked")
759	    final Map<String, String[]> parameterMap =
760	        (Map<String, String[]>) hsr.getParameterMap();
761	    final String pathInfo = hsr.getPathInfo();
762	    final String user = hsr.getRemoteUser();
763	    final Principal principal = hsr.getUserPrincipal();
